/*
*   test_draco_loading - Headless integration test for Draco-compressed glTF loading
*
*   Loads the GLB assets generated by generate_draco_assets.py through the public
*   raylib API (LoadModel) and validates the decoded mesh data.
*
*   The test runs without a window/GL context: the few rlgl functions used by
*   UploadMesh()/LoadTextureFromImage() are intercepted with the GNU ld --wrap
*   mechanism (see build command in tools/draco/README.md).
*
*   Run from the repository root. Exit code 0 means all tests passed.
*
*   Build with -DTEST_EXPECT_DRACO when raylib was built with SUPPORT_DRACO,
*   otherwise the Draco assets are expected to be skipped with warnings.
*/

#include "raylib.h"

#include <math.h>
#include <stdio.h>
#include <string.h>

// rlgl stubs (linked with -Wl,--wrap=<symbol>) so no GL context is needed
unsigned int __wrap_rlLoadVertexArray(void) { static unsigned int id = 0; return ++id; }
bool __wrap_rlEnableVertexArray(unsigned int vaoId) { (void)vaoId; return true; }
void __wrap_rlDisableVertexArray(void) { }
void __wrap_rlUnloadVertexArray(unsigned int vaoId) { (void)vaoId; }
unsigned int __wrap_rlLoadVertexBuffer(const void *buffer, int size, bool dynamic) { (void)buffer; (void)size; (void)dynamic; static unsigned int id = 100; return ++id; }
unsigned int __wrap_rlLoadVertexBufferElement(const void *buffer, int size, bool dynamic) { (void)buffer; (void)size; (void)dynamic; static unsigned int id = 200; return ++id; }
void __wrap_rlUnloadVertexBuffer(unsigned int vboId) { (void)vboId; }
void __wrap_rlEnableVertexBuffer(unsigned int id) { (void)id; }
void __wrap_rlDisableVertexBuffer(void) { }
void __wrap_rlEnableVertexBufferElement(unsigned int id) { (void)id; }
void __wrap_rlDisableVertexBufferElement(void) { }
void __wrap_rlSetVertexAttribute(unsigned int index, int compSize, int type, bool normalized, int stride, int offset)
{ (void)index; (void)compSize; (void)type; (void)normalized; (void)stride; (void)offset; }
void __wrap_rlEnableVertexAttribute(unsigned int index) { (void)index; }
void __wrap_rlDisableVertexAttribute(unsigned int index) { (void)index; }
void __wrap_rlSetVertexAttributeDefault(int locIndex, const void *value, int attribType, int count)
{ (void)locIndex; (void)value; (void)attribType; (void)count; }
void __wrap_rlSetVertexAttributeDivisor(unsigned int index, int divisor) { (void)index; (void)divisor; }
unsigned int __wrap_rlLoadTexture(const void *data, int width, int height, int format, int mipmapCount)
{ (void)data; (void)width; (void)height; (void)format; (void)mipmapCount; static unsigned int id = 300; return ++id; }
void __wrap_rlUnloadTexture(unsigned int id) { (void)id; }
void __wrap_rlGenTextureMipmaps(unsigned int id, int width, int height, int format, int *mipmaps)
{ (void)id; (void)width; (void)height; (void)format; (void)mipmaps; }

static int testsRun = 0;
static int testsFailed = 0;

#define TEST_DIR "examples/models/resources/models/gltf/draco"

static void Check(bool condition, const char *name)
{
    testsRun++;
    if (condition) printf("[PASS] %s\n", name);
    else { printf("[FAIL] %s\n", name); testsFailed++; }
}

static bool FloatNear(float a, float b, float epsilon) { return fabsf(a - b) < epsilon; }

static void TestCubeMultiAttr(void)
{
    printf("--- draco_cube_multiattr.glb (multi-attribute, indexed, transformed node)\n");
    Model model = LoadModel(TEST_DIR "/draco_cube_multiattr.glb");

#if !defined(TEST_EXPECT_DRACO)
    // No Draco support: the mesh must be skipped with a diagnosable warning, not crash
    Check(model.meshCount == 0, "cube: skipped without Draco support, no crash");
    UnloadModel(model);
    return;
#endif

    Check(model.meshCount == 1, "cube: meshCount == 1");
    if (model.meshCount != 1) return;

    Mesh mesh = model.meshes[0];
    Check(mesh.vertexCount == 24, "cube: vertexCount == 24");
    Check(mesh.triangleCount == 12, "cube: triangleCount == 12");
    Check(mesh.vertices != NULL, "cube: positions decoded");
    Check(mesh.normals != NULL, "cube: normals decoded");
    Check(mesh.tangents != NULL, "cube: tangents decoded");
    Check(mesh.texcoords != NULL, "cube: texcoords decoded");
    Check(mesh.colors != NULL, "cube: colors decoded");
    Check(mesh.indices != NULL, "cube: indices decoded");

    // Node transform: translation (1,2,3), scale 0.5, unit cube (-1..1) -> bbox (0.5,1.5,2.5)-(1.5,2.5,3.5)
    if (mesh.vertices != NULL)
    {
        Vector3 min = { 1e9f, 1e9f, 1e9f }, max = { -1e9f, -1e9f, -1e9f };
        for (int i = 0; i < mesh.vertexCount; i++)
        {
            for (int c = 0; c < 3; c++)
            {
                float v = mesh.vertices[3*i + c];
                if (v < (&min.x)[c]) (&min.x)[c] = v;
                if (v > (&max.x)[c]) (&max.x)[c] = v;
            }
        }
        Check(FloatNear(min.x, 0.5f, 0.01f) && FloatNear(min.y, 1.5f, 0.01f) && FloatNear(min.z, 2.5f, 0.01f) &&
              FloatNear(max.x, 1.5f, 0.01f) && FloatNear(max.y, 2.5f, 0.01f) && FloatNear(max.z, 3.5f, 0.01f),
              "cube: node transform applied to positions");
    }

    if (mesh.normals != NULL)
    {
        // NOTE: Node scale is 0.5, the inverse-transpose transform scales unit normals by 2.0
        // (same behavior as the uncompressed glTF loading path)
        bool unitNormals = true;
        for (int i = 0; i < mesh.vertexCount; i++)
        {
            float len = sqrtf(mesh.normals[3*i]*mesh.normals[3*i] + mesh.normals[3*i+1]*mesh.normals[3*i+1] + mesh.normals[3*i+2]*mesh.normals[3*i+2]);
            if (!FloatNear(len, 2.0f, 0.01f)) unitNormals = false;
        }
        Check(unitNormals, "cube: normals transformed by inverse-transpose matrix");
    }

    if (mesh.indices != NULL)
    {
        bool indicesInRange = true;
        for (int i = 0; i < mesh.triangleCount*3; i++)
        {
            if (mesh.indices[i] >= 24) indicesInRange = false;
        }
        Check(indicesInRange, "cube: indices in range");
    }

    // Material must be preserved: baseColorFactor (0.8, 0.6, 0.4, 1.0)
    Check(model.meshMaterial[0] == 1, "cube: material assigned");
    if (model.meshMaterial[0] == 1)
    {
        Color tint = model.materials[1].maps[MATERIAL_MAP_ALBEDO].color;
        Check(tint.r == 204 && tint.g == 153 && tint.b == 102 && tint.a == 255, "cube: material base color factor preserved");
    }

    UnloadModel(model);
}

static void TestSkinned(void)
{
    printf("--- draco_skinned.glb (skinned, JOINTS_0/WEIGHTS_0 from Draco)\n");
    Model model = LoadModel(TEST_DIR "/draco_skinned.glb");

#if !defined(TEST_EXPECT_DRACO)
    Check(model.meshCount == 0, "skin: skipped without Draco support, no crash");
    UnloadModel(model);
    return;
#endif

    Check(model.meshCount == 1, "skin: meshCount == 1");
    if (model.meshCount != 1) return;

    Mesh mesh = model.meshes[0];
    Check(mesh.vertexCount == 18, "skin: vertexCount == 18");
    Check(mesh.triangleCount == 16, "skin: triangleCount == 16");
    Check(model.skeleton.boneCount == 2, "skin: 2 bones loaded");
    Check(mesh.boneIndices != NULL, "skin: boneIndices decoded from Draco");
    Check(mesh.boneWeights != NULL, "skin: boneWeights decoded from Draco");

    if (mesh.boneIndices != NULL)
    {
        bool jointsOk = true;
        for (int i = 0; i < mesh.vertexCount; i++)
        {
            if (mesh.boneIndices[4*i] != 0 || mesh.boneIndices[4*i + 1] != 1) jointsOk = false;
        }
        Check(jointsOk, "skin: joint ids (0,1) per vertex");
    }

    if (mesh.boneWeights != NULL)
    {
        bool weightsOk = true;
        for (int i = 0; i < mesh.vertexCount; i++)
        {
            float sum = mesh.boneWeights[4*i] + mesh.boneWeights[4*i + 1];
            if (!FloatNear(sum, 1.0f, 0.01f)) weightsOk = false;
        }
        Check(weightsOk, "skin: weights normalized per vertex");
    }

    UnloadModel(model);
}

static void TestCorrupted(void)
{
    printf("--- draco_corrupted.glb (truncated Draco stream, must fail gracefully)\n");
    Model model = LoadModel(TEST_DIR "/draco_corrupted.glb");

    // The corrupted mesh must be skipped with a diagnosable error, not crash
    Check(model.meshCount == 0, "corrupted: no meshes loaded, no crash");

    UnloadModel(model);
}

static void TestUndeclared(void)
{
    printf("--- draco_undeclared.glb (extension not declared in extensionsUsed)\n");
    Model model = LoadModel(TEST_DIR "/draco_undeclared.glb");

#if !defined(TEST_EXPECT_DRACO)
    Check(model.meshCount == 0, "undeclared: skipped without Draco support, no crash");
    UnloadModel(model);
    return;
#endif

    Check(model.meshCount == 1, "undeclared: meshCount == 1 (decoded with warning)");
    if (model.meshCount == 1) Check(model.meshes[0].vertexCount == 24, "undeclared: vertexCount == 24");

    UnloadModel(model);
}

static void TestUncompressedStillWorks(void)
{
    printf("--- greenman.glb (uncompressed asset in Draco-enabled build)\n");
    Model model = LoadModel("examples/models/resources/models/gltf/greenman.glb");

    Check(model.meshCount > 0, "uncompressed: meshCount > 0");
    if (model.meshCount > 0) Check(model.meshes[0].vertexCount > 0, "uncompressed: vertexCount > 0");

    UnloadModel(model);
}

static void TestMixedContent(void)
{
    printf("--- draco_mixed.glb (Draco + uncompressed meshes in one file)\n");
    Model model = LoadModel(TEST_DIR "/draco_mixed.glb");

#if defined(TEST_EXPECT_DRACO)
    Check(model.meshCount == 2, "mixed: both meshes loaded");
    if (model.meshCount == 2)
    {
        Check(model.meshes[0].vertexCount == 24, "mixed: Draco mesh vertexCount == 24");
        Check(model.meshes[1].vertexCount == 3, "mixed: uncompressed mesh vertexCount == 3");
    }
#else
    // Without Draco support the uncompressed mesh must still load
    Check(model.meshCount == 1, "mixed: uncompressed mesh loaded without Draco support");
    if (model.meshCount == 1) Check(model.meshes[0].vertexCount == 3, "mixed: vertexCount == 3");
#endif

    UnloadModel(model);
}

int main(void)
{
    SetTraceLogLevel(LOG_ALL);

    TestCubeMultiAttr();
    TestSkinned();
    TestCorrupted();
    TestUndeclared();
    TestUncompressedStillWorks();
    TestMixedContent();

    printf("--------------------------------------------------\n");
    printf("%i tests run, %i failed\n", testsRun, testsFailed);

    return (testsFailed == 0)? 0 : 1;
}
